CREATE view Q_BEDEHBESTANH_MAIN as   SELECT     dbo.Q_BEDEHBESTANHA.TAFZIL, dbo.Q_BEDEHBESTANHA.HES_K, dbo.Q_BEDEHBESTANHA.HES_M, dbo.Q_BEDEHBESTANHA.SumOfBED, dbo.Q_BEDEHBESTANHA.SumOfBES,dbo.Q_BEDEHBESTANHA.BEDBES, dbo.Q_BEDEHBESTANHA.NAME, dbo.Q_BEDEHBESTANHA.MOIN, dbo.UIIF(dbo.Q_BEDEHBESTANHA.BEDBES, '>', 0, dbo.Q_BEDEHBESTANHA.BEDBES, 0) AS BEDM, dbo.UIIF(dbo.Q_BEDEHBESTANHA.BEDBES, '<', 0, dbo.Q_BEDEHBESTANHA.BEDBES * - 1, 0) AS BESM, dbo.Q_BEDEHBESTANHA.HES_T, dbo.Q_BEDEHBESTANHA.ADDRESS,dbo.Q_BEDEHBESTANHA.TEL, dbo.Q_BEDEHBESTANHA.CODE_E, dbo.Q_BEDEHBESTANHA.TOZIH, dbo.Q_BEDEHBESTANHA.HES, dbo.Q_BEDEHBESTANHA.ECODE,dbo.Q_BEDEHBESTANHA.CUST_COD, dbo.Q_BEDEHBESTANHA.ROUTE_NAME, dbo.Visit_route.HES AS VCOD, dbo.CUST_HESAB.NAME AS VNAME, dbo.Q_BEDEHBESTANHA.HES_T2,dbo.Q_BEDEHBESTANHA.HES_T3, CUST_HESAB_1.NAME AS tafname, dbo.Q_BEDEHBESTANHA.Latitude, dbo.Q_BEDEHBESTANHA.Longitude, dbo.Q_BEDEHBESTANHA.HES_T4, CUST_HESAB_1.Latitude * CUST_HESAB_1.Longitude AS charjm, ROUND(dbo.UIIF(dbo.Q_BEDEHBESTANHA.BEDBES, N'>', 0, dbo.Q_BEDEHBESTANHA.BEDBES, 0) / dbo.UIIF(CUST_HESAB_1.Latitude * CUST_HESAB_1.Longitude, N'>', 0, CUST_HESAB_1.Latitude * CUST_HESAB_1.Longitude, 1), 0) AS mah, dbo.Q_BEDEHBESTANHA.MOBILE,CUST_HESAB_1.OSTANID , CUST_HESAB_1.SHAHRID FROM         dbo.CUST_HESAB CUST_HESAB_1 INNER JOIN dbo.Q_BEDEHBESTANHA ON CUST_HESAB_1.hes = dbo.Q_BEDEHBESTANHA.HES LEFT OUTER JOIN dbo.CUST_HESAB INNER JOIN dbo.Visit_route ON dbo.CUST_HESAB.hes = dbo.Visit_route.HES ON dbo.Q_BEDEHBESTANHA.ROUTE_NAME = dbo.Visit_route.ROUTE_NAME
